var o=[{title:`Leggere il rapporto`,text:`Un intervallo 1:3 potrebbe essere 20 secondi di sforzo e 60 secondi di recupero, un intervallo 1:1 potrebbe essere 30 secondi ciascuno, e 2:1 potrebbe essere 40 secondi di lavoro e 20 secondi facili. Il rapporto da solo non descrive l’allenamento finché non conosci durata e intensità.`},{title:`Recupero lungo per la qualità`,text:`Riposi abbastanza lunghi ti aiutano a mantenere velocità o potenza nel corso di brevi sforzi duri. Un’impostazione 1:3 può andare bene per chi pratica una corsa più veloce o un movimento impegnativo e vuole evitare di stancarsi subito. Uno sprint molto intenso può richiedere un recupero molto più lungo di 1:3 per mantenere alta la resa.`},{title:`Recupero uguale o breve`,text:`Con 1:1, lavoro e recupero durano lo stesso tempo. Con 2:1, il recupero è più breve, quindi la fatica può accumularsi in fretta. Questi formati possono funzionare per circuiti moderati, ma non sono automaticamente migliori per obiettivi avanzati di resistenza o forza.`},{title:`Adatta in base alla capacità e all’esercizio`,text:`Un principiante potrebbe camminare a passo svelto per 30 secondi e con calma per 90 secondi, poi allungare lentamente il lavoro. Un ciclista allenato può usare sforzi duri più lunghi con un recupero generoso. I movimenti con salti spesso richiedono più controllo tecnico, quindi scegli un riposo che mantenga buoni i tuoi atterraggi. Valuta i progressi in base a se finisci con buona tecnica, allunga il riposo quando serve e non rendere ogni intervallo più difficile solo per accorciare l’allenamento.`}];var a=[{label:`ACE: progettare intervalli ad alta intensità`,url:`https://www.acefitness.org/continuing-education/certified/may-2021/7844/how-to-use-the-ace-ift-model-to-design-effective-hiit-workouts/`},{label:`CDC: misurare l’intensità dell’attività e il talk test`,url:`https://www.cdc.gov/physicalactivity/basics/measuring/index.html`},{label:`CDC: raccomandazioni sull’attività fisica per gli adulti`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`}];var t={sections:o,sources:a};export{t as default,o as sections,a as sources};